        names = [self.ident()]
        while self.is_op(","):
            self.next()
            names.append(self.ident())
        return tuple(names)

    def literal_value(self) -> Value:
        tok = self.next()
        if tok.type is TokenType.INTEGER:
            return int(tok.value)
        if tok.type is TokenType.STRING:
            return tok.value
        if tok.type is TokenType.KEYWORD:
            if tok.value == "TRUE":
                return True
            if tok.value == "FALSE":
                return False
            if tok.value == "NULL":
                return None
        raise SQLSyntaxError(f"expected literal, got {tok.value!r}")

    def statement(self) -> Statement:
        tok = self.peek()
        if tok.type is not TokenType.KEYWORD:
            raise SQLSyntaxError(f"expected statement, got {tok.value!r}")
        if tok.value == "CREATE":
            return self.create()
        if tok.value == "DROP":
            self.next()
            self.expect_kw("TABLE")
            return DropTableStmt(self.ident())
        if tok.value == "INSERT":
            return self.insert()
        if tok.value == "SELECT":
            return self.select()
        if tok.value == "DELETE":
            self.next()
            self.expect_kw("FROM")
            table = self.ident()
            return DeleteStmt(table, self.opt_where())
        raise SQLSyntaxError(f"unexpected keyword {tok.value!r}")

